import { ChartLocaleProvider } from '@gntik-ai/charts';
import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import {
  SidebarLayout,
  useI18n,
  type BreadcrumbItem,
  type NavGroup,
  type SidebarLayoutProps,
  type UserMenuUser,
  type Workspace,
} from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends
    Omit<AppSidebarHeaderProps, 'collapsed' | 'className' | 'workspaces'>,
    Pick<
      AppSidebarFooterProps,
      'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'userMenuChildren' | 'onSignOut'
    >,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  userMenuChildren,
  brand,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
  ...contextProps
}: ConsoleShellProps) {
  const { locale } = useI18n();
  return (
    <ChartLocaleProvider locale={locale}>
      <SidebarLayout
        fullScreen
        storageKey={storageKey}
        sidebarLabel={sidebarLabel}
        collapseMode={collapseMode}
        sidebarHeader={({ collapsed }) => (
          <AppSidebarHeader
            collapsed={collapsed}
            workspaces={workspaces}
            currentWorkspaceId={currentWorkspaceId}
            onWorkspaceChange={onWorkspaceChange}
            onCreateWorkspace={onCreateWorkspace}
            brand={brand}
            {...contextProps}
          />
        )}
        sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
        sidebarFooter={({ collapsed }) => (
          <AppSidebarFooter
            collapsed={collapsed}
            user={user}
            usage={usage}
            helpHref={helpHref}
            helpLabel={helpLabel}
            userMenuItems={userMenuItems}
            userMenuChildren={userMenuChildren}
            onSignOut={onSignOut}
          />
        )}
        topbar={
          brand == null ? (
            <AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />
          ) : (
            <>
              <div className="min-w-0 shrink-0 lg:hidden">{brand}</div>
              <AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />
            </>
          )
        }
      >
        {children}
      </SidebarLayout>
    </ChartLocaleProvider>
  );
}

import { useI18n } from '@gntik-ai/ui';
import {
  ChartCard,
  DataTable,
  DateRangeFilter,
  FilterBar,
  NoResultsEmpty,
  PageHeader,
  type ActiveFilter,
  type ChartCardProps,
  type ChartCardRange,
  type CostPoint,
  type DataTableColumn,
  type FilterField,
  type SavedView,
} from '@gntik-ai/blocks';
import { chartFmt } from '@gntik-ai/charts';
import { Download } from '@gntik-ai/icons';
import { Grid, HStack, Page, Section, Stack, type BreadcrumbItem, type DateRange } from '@gntik-ai/ui';
import { useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import {
  filterUsage,
  trafficByRange,
  trafficRanges,
  usageBreadcrumbs,
  usageColumns,
  usageFilterFields,
  usageRows,
  usageSavedViews,
  type TrafficPoint,
  type UsageRow,
} from './data';

export interface UsageExportRequest {
  range: DateRange | null;
  query: string;
  filters: ActiveFilter[];
  /** Rows currently shown in the breakdown. */
  rows: UsageRow[];
}

/** Second-chart settings (everything but its data and ranges, which have their own props). */
export type UsageSecondaryChart<T extends object> = Omit<ChartCardProps<T>, 'dataByRange' | 'ranges'>;

/**
 * `P` is the row type of the first chart (default: the infrastructure-cost fixture), `T` the row
 * type of the second one (default: requests per environment and day).
 */
export interface UsageAnalyticsProps<P extends object = CostPoint, T extends object = TrafficPoint> {
  title: string;
  description: string;
  breadcrumbs: BreadcrumbItem[];
  rows: readonly UsageRow[];
  /** Breakdown table columns (default: project, environment, region, requests, error rate, cost). */
  columns: DataTableColumn<UsageRow>[];
  /** FilterBar fields; each id is matched against the row field of the same name. */
  filterFields: FilterField[];
  searchPlaceholder: string;
  savedViews: readonly SavedView[];
  /**
   * First chart: any ChartCard props (title, description, ranges, dataByRange, index, categories,
   * colors, kind, valueFormatter…). Unset fields keep the infrastructure-cost fixture.
   */
  primaryChart: ChartCardProps<P>;
  /** Data of the second chart, per range key. */
  trafficByRange: Readonly<Record<string, readonly T[]>>;
  trafficRanges: readonly ChartCardRange[];
  /** Second chart: title, description, index, categories, colors, kind… (merged over the traffic defaults). */
  secondaryChart: UsageSecondaryChart<T>;
  /** Fires when the date range changes (server-side products refetch here). */
  onRangeChange: (range: DateRange) => void;
  onExport: (request: UsageExportRequest) => void;
  shell: Omit<ConsoleShellProps, 'children'>;
}

const TRAFFIC_CHART: UsageSecondaryChart<TrafficPoint> = {
  title: 'Requests by environment',
  description: 'Daily requests',
  index: 'day',
  categories: ['Production', 'Staging', 'Preview'],
  kind: 'bar',
  valueFormatter: chartFmt.compact,
};

/** Usage analytics: date range + filters, two charts and a sortable breakdown table with export. */
export default function UsageAnalyticsPage<P extends object = CostPoint, T extends object = TrafficPoint>({
  title = 'Usage analytics',
  description = 'Traffic, errors and spend by project and environment.',
  breadcrumbs = usageBreadcrumbs,
  rows = usageRows,
  columns = usageColumns,
  filterFields = usageFilterFields,
  searchPlaceholder = 'Search projects…',
  savedViews = usageSavedViews,
  primaryChart,
  trafficByRange: traffic = trafficByRange as unknown as Readonly<Record<string, readonly T[]>>,
  trafficRanges: ranges = trafficRanges,
  secondaryChart,
  onRangeChange,
  onExport,
  shell,
}: Partial<UsageAnalyticsProps<P, T>>) {
  const { locale } = useI18n();
  const secondary = { ...(TRAFFIC_CHART as unknown as UsageSecondaryChart<T>), ...secondaryChart };
  const [range, setRange] = useState<DateRange | null>(null);
  const [query, setQuery] = useState('');
  const [filters, setFilters] = useState<ActiveFilter[]>([]);
  const visible = filterUsage(rows, query, filters, locale);

  const clearFilters = () => setFilters([]);
  const exportAction = {
    label: 'Export CSV',
    icon: Download,
    variant: 'secondary' as const,
    onClick: () => onExport?.({ range, query, filters, rows: visible }),
  };

  return (
    <ConsoleShell currentHref="/analytics" breadcrumbs={breadcrumbs} {...shell}>
      <Page
        width="wide"
        header={
          <PageHeader
            breadcrumbs={null}
            title={title}
            description={description}
            status=""
            meta={[]}
            tabs={null}
            actions={[exportAction]}
          />
        }
      >
        <Stack gap={6}>
          <HStack align="start" gap={3} wrap>
            <DateRangeFilter
              onValueChange={(next) => {
                setRange(next);
                onRangeChange?.(next);
              }}
            />
            <FilterBar
              className="min-w-0 flex-1"
              fields={filterFields}
              query={query}
              onQueryChange={setQuery}
              filters={filters}
              onFiltersChange={setFilters}
              defaultFilters={[]}
              views={savedViews}
              placeholder={searchPlaceholder}
              resultCount={visible.length}
            />
          </HStack>
          <Grid cols={{ base: 1, lg: 2 }} gap={6}>
            <ChartCard<P> titleAs="h2" {...primaryChart} />
            <ChartCard<T> titleAs="h2" {...secondary} ranges={ranges} dataByRange={traffic} />
          </Grid>
          <Section title="Breakdown" description="Per project and environment. Sort by any column.">
            <DataTable<UsageRow>
              rows={visible}
              columns={columns}
              getRowLabel={(r) => `${r.project} (${r.environment})`}
              caption="Usage by project"
              selectable={false}
              showDensityToggle
              showColumnMenu
              defaultSort={{ columnId: 'cost', direction: 'descending' }}
              emptyState={
                <NoResultsEmpty
                  entity="projects"
                  query={query}
                  filterCount={filters.length}
                  onClearFilters={clearFilters}
                  onClearSearch={() => setQuery('')}
                  titleAs="h3"
                />
              }
            />
          </Section>
        </Stack>
      </Page>
    </ConsoleShell>
  );
}

import { matchText } from '@gntik-ai/ui';
import type { ActiveFilter, ChartCardRange, DataTableColumn, FilterField, SavedView } from '@gntik-ai/blocks';
import type { BreadcrumbItem } from '@gntik-ai/ui';

/** One row of the usage breakdown table. */
export interface UsageRow {
  id: string;
  project: string;
  /** Environment name, e.g. "Production". */
  environment: string;
  region: string;
  requests: number;
  errorRate: number;
  cost: number;
}

export interface TrafficPoint {
  day: string;
  Production: number;
  Staging: number;
  Preview: number;
}

export const usageBreadcrumbs: BreadcrumbItem[] = [{ label: 'Overview', href: '/overview' }, { label: 'Analytics' }];

const PROJECTS = [
  'orders-api',
  'billing-sync',
  'search-index',
  'auth-gateway',
  'media-resizer',
  'webhooks',
  'reports',
  'checkout-web',
];
const ENVS = ['Production', 'Production', 'Staging', 'Preview'];
const REGIONS = ['eu-west-1', 'us-east-1', 'ap-south-1', 'eu-central-1'];

/** Usage per project and environment over the selected range. */
export const usageRows: UsageRow[] = Array.from({ length: 16 }, (_, i) => ({
  id: `use_${i + 1}`,
  project: PROJECTS[i % PROJECTS.length] ?? 'orders-api',
  environment: ENVS[(i * 3) % ENVS.length] ?? 'Production',
  region: REGIONS[(i * 5) % REGIONS.length] ?? 'eu-west-1',
  requests: ((i * 48_271) % 900_000) + 12_000,
  errorRate: Math.round(((i * 37) % 29) * 0.11 * 100) / 100,
  cost: Math.round((((i * 3571) % 1_400) + 60) * 100) / 100,
}));

export const usageFilterFields: FilterField[] = [
  { id: 'environment', label: 'Environment', options: ['Production', 'Staging', 'Preview'] },
  { id: 'region', label: 'Region', options: REGIONS },
];

export const usageSavedViews: SavedView[] = [
  { value: 'all', label: 'All usage', filters: [] },
  { value: 'production', label: 'Production only', filters: [{ field: 'environment', value: 'Production' }] },
  {
    value: 'eu',
    label: 'EU regions',
    filters: [
      { field: 'region', value: 'eu-west-1' },
      { field: 'region', value: 'eu-central-1' },
    ],
  },
];

/**
 * Search by project name; filters match the row field named by the filter id (same field OR,
 * across fields AND). Filters on fields the row does not have are ignored.
 */
export function filterUsage(
  rows: readonly UsageRow[],
  query: string,
  filters: readonly ActiveFilter[],
  locale?: string,
): UsageRow[] {
  const q = query.trim();
  const byField = new Map<string, string[]>();
  for (const f of filters) byField.set(f.field, [...(byField.get(f.field) ?? []), f.value]);
  return rows.filter((row) => {
    if (q && !matchText(row.project, q, { locale })) return false;
    for (const [field, values] of byField) {
      const value: unknown = (row as unknown as Record<string, unknown>)[field];
      if (value !== undefined && value !== null && !values.includes(String(value))) return false;
    }
    return true;
  });
}

const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
const count = new Intl.NumberFormat('en-US');

export const usageColumns: DataTableColumn<UsageRow>[] = [
  {
    id: 'project',
    header: 'Project',
    accessor: (r) => r.project,
    sortable: true,
    hideable: false,
    className: 'font-semibold',
  },
  { id: 'environment', header: 'Environment', accessor: (r) => r.environment, sortable: true },
  {
    id: 'region',
    header: 'Region',
    accessor: (r) => r.region,
    sortable: true,
    className: 'font-mono text-[12px] text-muted-foreground',
  },
  {
    id: 'requests',
    header: 'Requests',
    accessor: (r) => r.requests,
    cell: (r) => count.format(r.requests),
    sortable: true,
    align: 'right',
    className: 'font-mono text-[12.5px]',
  },
  {
    id: 'errors',
    header: 'Error rate',
    accessor: (r) => r.errorRate,
    cell: (r) => `${r.errorRate.toFixed(2)}%`,
    sortable: true,
    align: 'right',
    className: 'font-mono text-[12.5px]',
  },
  {
    id: 'cost',
    header: 'Cost',
    accessor: (r) => r.cost,
    cell: (r) => money.format(r.cost),
    sortable: true,
    align: 'right',
    className: 'font-mono text-[12.5px]',
  },
];

const DAYS7 = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const DAYS30 = Array.from({ length: 30 }, (_, i) => `Day ${i + 1}`);
const traffic = (labels: string[], base: number): TrafficPoint[] =>
  labels.map((day, i) => ({
    day,
    Production: Math.round(base + ((i * 37) % 11) * 900),
    Staging: Math.round(base * 0.22 + ((i * 13) % 7) * 210),
    Preview: Math.round(base * 0.08 + ((i * 29) % 5) * 120),
  }));

/** Requests per environment, per range. */
export const trafficByRange: Record<string, TrafficPoint[]> = {
  '7d': traffic(DAYS7, 24_000),
  '30d': traffic(DAYS30, 22_000),
};

export const trafficRanges: ChartCardRange[] = [
  {
    value: '7d',
    label: '7d',
    summary: { value: '241,906', delta: { value: '+8.2%', direction: 'up', sentiment: 'positive' } },
  },
  {
    value: '30d',
    label: '30d',
    summary: { value: '1.02M', delta: { value: '+3.5%', direction: 'up', sentiment: 'positive' } },
  },
];
